"""All 68 direction/context groups x nine fixed CM activity support diagnostics.
Descriptive, no post-hoc gate or primary result mutation.
"""
from pathlib import Path
from datetime import datetime,timezone
import os,json,hashlib
import pandas as pd,numpy as np
from scipy.stats import spearmanr
sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest()
def main():
 R=Path(os.environ['PANCANCER_PREFLIGHT_ROOT']);AR=Path(os.environ['PANCANCER_ANNOTATION_ROOT']);P=R/'immune_same_name_family_source_review_v1';B=AR/'20261010_expression_annotation_downstream_v1';L=P/'CM_edge_LR_extraction_v2';C=P/'CM_edge_coverage_v1';O=P/'CM_activity_member_support_diagnostic_v1';planpath=Path(os.environ['PANCANCER_CM_SUPPORT_PLAN']);plan=json.loads(planpath.read_text());assert not O.exists() and sha(__file__)==plan['producer_sha256'];assert sha(C/'inventory.json')==plan['coverage_inventory_sha256'];inv=json.loads((C/'inventory.json').read_text());paths=dict(W=B/'covarnet/tables/nmf_W_subcluster_by_cm.tsv',H=B/'covarnet/tables/nmf_H_cm_by_sample.tsv',F=B/'covarnet/tables/frequency_normalized.tsv',counts=B/'inputs/sample_major_subcluster_counts.tsv',catalogue=B/'downstream_review_v2/number_to_annotation_dictionary.tsv')
 for k,f in paths.items():assert sha(f)==inv['input_sha256'][k]['sha256']
 W=pd.read_csv(paths['W'],sep='\t',index_col=0);H=pd.read_csv(paths['H'],sep='\t',index_col=0);F=pd.read_csv(paths['F'],sep='\t',index_col=0);counts=pd.read_csv(paths['counts'],sep='\t');cat=pd.read_csv(paths['catalogue'],sep='\t').set_index('subCluster');n=counts.pivot_table(index='sampleID',columns='subCluster',values='n_cells',aggfunc='sum',fill_value=0).reindex(columns=W.index,fill_value=0);groups=pd.read_csv(L/'all68_directed_group_summary.tsv',sep='\t');top={c:W[c].sort_values(ascending=False,kind='stable').index[:10].tolist() for c in W};rows=[]
 for group in groups.itertuples():
  b=dict(np.load(L/'private_group_arrays'/(group.group_id+'.npz'),allow_pickle=False));samples=b['samples'];keep=~W.index.isin([group.source,group.target]);x=F.loc[keep,samples].to_numpy().T;prediction=b['endpoint_excluded_activity']@W.loc[keep].to_numpy().T;error=np.linalg.norm(x-prediction,axis=1)/np.maximum(np.linalg.norm(x,axis=1),1e-12)
  for i,cm in enumerate(W):
   nodes=[v for v in top[cm] if v not in [group.source,group.target]];cells=n.loc[samples,nodes].to_numpy();present=(cells>=20).sum(axis=1);weights=W.loc[nodes,cm].to_numpy();fraction=((cells>=20)*weights).sum(axis=1)/weights.sum();a=b['endpoint_excluded_activity'][:,i];h=H.loc[cm,samples].to_numpy();rho=float(spearmanr(a,h).statistic) if np.std(a)>1e-12 and np.std(h)>1e-12 else None;rows.append(dict(group_id=group.group_id,pair_id=group.pair_id,gse_id=group.gse_id,stratum=group.stratum,source=group.source,target=group.target,cm=cm,n_endpoint_libraries=len(samples),n_remaining_fixed_top10_members=len(nodes),median_remaining_top10_ge20=float(np.median(present)),min_remaining_top10_ge20=int(present.min()),median_remaining_top10_weight_captured_ge20=float(np.median(fraction)),n_libraries_zero_remaining_top10_ge20=int((present==0).sum()),median_all_node_NNLS_relative_reconstruction_error=float(np.median(error)),endpoint_excluded_activity_positive_libraries=int((a>1e-10).sum()),originalH_zero_but_excluded_activity_positive=int(((h<=1e-10)&(a>1e-10)).sum()),activity_originalH_spearman=rho,primary_inference_unchanged=True))
 assert len(rows)==612;O.mkdir();d=pd.DataFrame(rows);d.to_csv(O/'all612_fixedCM_member_support_diagnostics.tsv',sep='\t',index=False,na_rep='NA');t=pd.DataFrame([dict(cm=cm,fixed_top10_nodes=';'.join(nodes),fixed_top10_major_types=';'.join(cat.loc[nodes,'majorCluster'])) for cm,nodes in top.items()]);t.to_csv(O/'fixed9CM_top10_member_dictionary.tsv',sep='\t',index=False);report=dict(plan_sha256=sha(planpath),status='COMPLETE_DESCRIPTIVE_SUPPORT_DIAGNOSTIC_NOT_NEW_STATISTICAL_GATE',observed_UTC=datetime.now(timezone.utc).isoformat(),producer_sha256=sha(__file__),all_group_CM_rows=612,fixed_top10_rule='descending frozen W, stable original row-order ties, remove endpoints without replacing them',no_primary_result_or_gate_change=True,no_p_or_functional_validation=True,input_sha256={k:sha(f) for k,f in paths.items()},outputs={f.name:sha(f) for f in O.iterdir() if f.is_file()});(O/'inventory.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps(report),flush=True)
if __name__=='__main__':main()
